#include <iostream>
#include <vector>
#include <deque>
#include <cstring>
#include <climits>
#include <algorithm>
using namespace std;

char A[12][12], B[12][12];
int n, t;
bool vis[70][12][12][12][12];
bool reach[12][12][12][12];
int dist[12][12];
vector<vector<int>> adj;
int cap[210][210], flow[210][210];
int excess[210], height[210];
int nodeMap[11][11];

void propagate(int time, int x, int y, int sx, int sy) {
    if (t >= 70) return;
    if (x < 0 || x >= n || y < 0 || y >= n) return;
    if (A[x][y] < '0' || A[x][y] > '9') return;
    if (time > t + 1) return;
    if (vis[time][x][y][sx][sy]) return;
    if (time > dist[x][y] && dist[x][y] != 0) return;
    if (time == dist[x][y] && dist[x][y] != 0 && (B[x][y] > '9' || B[x][y] <= '0')) return;
    vis[time][x][y][sx][sy] = true;
    if (time < dist[x][y]) {
        propagate(time+1, x, y, sx, sy);
        propagate(time+1, x+1, y, sx, sy);
        propagate(time+1, x-1, y, sx, sy);
        propagate(time+1, x, y+1, sx, sy);
        propagate(time+1, x, y-1, sx, sy);
    }
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("1.txt", "rt", stdin);
#endif
    cin >> n >> t;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> A[i][j];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> B[i][j];

    deque<pair<int,int>> bfsQ;
    memset(dist, -1, sizeof(dist));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (A[i][j] == 'Z') {
                dist[i][j] = 0;
                bfsQ.emplace_back(i, j);
            }

    const int dx[] = {-1, 0, 1, 0};
    const int dy[] = {0, -1, 0, 1};
    while (!bfsQ.empty()) {
        auto [x, y] = bfsQ.front(); bfsQ.pop_front();
        if (dist[x][y] >= t) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                A[nx][ny] >= '0' && A[nx][ny] <= '9' && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[x][y] + 1;
                bfsQ.emplace_back(nx, ny);
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (dist[i][j] == -1) dist[i][j] = t;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (A[i][j] >= '0' && A[i][j] <= '9')
                propagate(0, i, j, i, j);

    for (int i1 = 0; i1 < n; ++i1)
        for (int j1 = 0; j1 < n; ++j1)
            for (int i2 = 0; i2 < n; ++i2)
                for (int j2 = 0; j2 < n; ++j2)
                    for (int nt = 0; nt <= t; ++nt)
                        reach[i1][j1][i2][j2] |= vis[nt][i1][j1][i2][j2];

    adj.resize(1);
    for (int i1 = 0; i1 < n; ++i1)
        for (int j1 = 0; j1 < n; ++j1)
            if (A[i1][j1] > '0' && A[i1][j1] <= '9') {
                int u = adj.size();
                adj.emplace_back();
                excess[u] = A[i1][j1] - '0';
                for (int i2 = 0; i2 < n; ++i2)
                    for (int j2 = 0; j2 < n; ++j2)
                        if (B[i2][j2] > '0' && B[i2][j2] <= '9' && reach[i2][j2][i1][j1]) {
                            int v;
                            if (nodeMap[i2][j2] == 0) {
                                nodeMap[i2][j2] = adj.size();
                                adj.emplace_back();
                            }
                            v = nodeMap[i2][j2];
                            adj[u].push_back(v);
                            adj[v].push_back(u);
                            cap[u][v] = 10000;
                            cap[v][u] = 0;
                        }
            }

    for (int i2 = 0; i2 < n; ++i2)
        for (int j2 = 0; j2 < n; ++j2)
            if (B[i2][j2] > '0' && B[i2][j2] <= '9' && nodeMap[i2][j2] > 0) {
                int v = nodeMap[i2][j2];
                adj[v].push_back(0);
                cap[v][0] = B[i2][j2] - '0';
                cap[0][v] = 0;
            }

    for (int i = 0; i < (int)adj.size(); ++i) height[i] = 0;
    height[0] = adj.size();

    while (true) {
        bool changed = false;
        for (int u = 1; u < (int)adj.size(); ++u) {
            while (excess[u] > 0) {
                bool pushed = false;
                int minHeight = INT_MAX;
                for (int v : adj[u]) {
                    if (cap[u][v] - flow[u][v] > 0) minHeight = min(minHeight, height[v]);
                    if (cap[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                        int delta = min(cap[u][v] - flow[u][v], excess[u]);
                        flow[u][v] += delta;
                        flow[v][u] -= delta;
                        excess[u] -= delta;
                        excess[v] += delta;
                        pushed = true;
                        changed = true;
                        if (excess[u] == 0) goto nextNode;
                    }
                }
                if (height[u] != minHeight + 1 && minHeight != INT_MAX) {
                    height[u] = minHeight + 1;
                    changed = true;
                }
                if (!pushed) nextNode: break;
            }
        }
        if (!changed) break;
    }

    cout << excess[0];
    return 0;
}
